export { default as Silk } from './Silk.vue';
export { isSilkPreset, silkPreset } from './silk-presets';
export type { SilkLook, SilkPreset, SilkProps } from './types';

import { SILK_COMPOSITE, SILK_FIELD, SILK_VERTEX } from './silk-shaders';
import type { SilkEngine, SilkProps, SilkSettings } from './types';

const INTRO_SECONDS = 2.2;
const INTRO_RUSH = 1.6;
const WAVE_LIFE = 1.6;
const DEFAULT_LIGHT_X = -0.55;
const DEFAULT_LIGHT_Y = 0.7;
const LIGHT_TILT = Math.hypot(DEFAULT_LIGHT_X, DEFAULT_LIGHT_Y);

interface LinkedProgram {
  program: WebGLProgram;
  uniform: (name: string) => WebGLUniformLocation | null;
}

interface Ripple {
  x: number;
  y: number;
  age: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const ease = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);

function variationShift(variation: number): [number, number] {
  const n = Number(variation) || 0;
  if (!n) return [0, 0];
  const wave = (k: number) => {
    const v = Math.sin(n * 12.9898 + k * 78.233) * 43758.5453;
    return v - Math.floor(v) - 0.5;
  };
  return [wave(1) * 6, wave(2) * 6];
}

export function toSilkSettings(props: SilkProps): SilkSettings {
  return {
    speed: props.speed ?? 5,
    scale: props.scale ?? 1,
    color: String(props.color ?? '#7B7481'),
    sheenColor: String(props.sheenColor ?? '#ffffff'),
    noiseIntensity: Math.max(0, props.noiseIntensity ?? 1.5),
    rotation: props.rotation ?? 0,
    sheen: Math.max(0, props.sheen ?? 0.5),
    depth: clamp(props.depth ?? 0.5, 0, 1),
    glow: Math.max(0, props.glow ?? 0.3),
    ripple: Math.max(0, props.ripple ?? 1),
    wave: Math.max(0, props.wave ?? 1),
    variation: props.variation ?? 0,
    mouseInteraction: props.mouseInteraction ?? true,
    interactionStrength: Math.max(0, props.interactionStrength ?? 1),
    clickRipple: props.clickRipple ?? true,
    intro: props.intro ?? true,
    fade: clamp(props.fade ?? 0, 0, 1),
    lightMode: props.lightMode ?? false,
    paused: props.paused ?? false,
    dpr: props.dpr,
  };
}

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
}

function link(
  gl: WebGL2RenderingContext,
  fragmentSource: string,
): LinkedProgram | null {
  const vertex = compile(gl, gl.VERTEX_SHADER, SILK_VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, fragmentSource);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, 'aPosition');
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const locations = new Map<string, WebGLUniformLocation | null>();
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) {
      locations.set(
        info.name.replace(/\[0\]$/, ''),
        gl.getUniformLocation(program, info.name),
      );
    }
  }
  return { program, uniform: (name) => locations.get(name) ?? null };
}

export function createSilkEngine(
  canvas: HTMLCanvasElement,
  getSettings: () => SilkSettings,
  isReduced: () => boolean,
  wake: () => void,
): SilkEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'high-performance',
  });
  if (!gl) return null;

  const fieldProgram = link(gl, SILK_FIELD);
  const compositeProgram = link(gl, SILK_COMPOSITE);
  const buffer = gl.createBuffer();
  const vao = gl.createVertexArray();
  const texture = gl.createTexture();
  const framebuffer = gl.createFramebuffer();
  if (
    !fieldProgram ||
    !compositeProgram ||
    !buffer ||
    !vao ||
    !texture ||
    !framebuffer
  ) {
    gl.getExtension('WEBGL_lose_context')?.loseContext();
    return null;
  }

  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

  const target = { width: 0, height: 0 };
  const sizeTarget = (width: number, height: number) => {
    if (target.width === width && target.height === height) return;
    target.width = width;
    target.height = height;
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA8,
      width,
      height,
      0,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      null,
    );
    gl.texParameteri(
      gl.TEXTURE_2D,
      gl.TEXTURE_MIN_FILTER,
      gl.LINEAR_MIPMAP_LINEAR,
    );
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    gl.framebufferTexture2D(
      gl.FRAMEBUFFER,
      gl.COLOR_ATTACHMENT0,
      gl.TEXTURE_2D,
      texture,
      0,
    );
  };

  const probe = document
    .createElement('canvas')
    .getContext('2d', { willReadFrequently: true });
  const colorCache = new Map<string, number[]>();
  const toRgb = (value: string) => {
    const cached = colorCache.get(value);
    if (cached) return cached;
    let rgb = [1, 1, 1];
    if (probe) {
      probe.clearRect(0, 0, 1, 1);
      probe.fillStyle = '#ffffff';
      probe.fillStyle = value;
      probe.fillRect(0, 0, 1, 1);
      const data = probe.getImageData(0, 0, 1, 1).data;
      rgb = [(data[0] ?? 0) / 255, (data[1] ?? 0) / 255, (data[2] ?? 0) / 255];
    }
    colorCache.set(value, rgb);
    return rgb;
  };

  const initial = getSettings();
  const view = { width: 1, height: 1, ratio: 1 };
  const pointer = { x: 0, y: 0, inside: false };
  const waves: Ripple[] = [];
  const waveData = new Float32Array(16);
  const state = {
    flow: 0,
    intro: initial.intro && !isReduced() ? 0 : 1,
    touch: 0,
    x: 0,
    y: 0,
    dragX: 0,
    dragY: 0,
    lightX: DEFAULT_LIGHT_X,
    lightY: DEFAULT_LIGHT_Y,
  };
  let last = 0;
  let visible = true;
  let looping = false;
  let lastDpr = initial.dpr;

  const setShared = (
    program: LinkedProgram,
    width: number,
    height: number,
    s: SilkSettings,
    unfold: number,
  ) => {
    const u = program.uniform;
    const [shiftX, shiftY] = variationShift(s.variation);
    gl.uniform2f(u('uView'), width, height);
    gl.uniform1f(u('uScale'), s.scale);
    gl.uniform1f(u('uRotation'), s.rotation);
    gl.uniform1f(u('uTime'), state.flow - INTRO_RUSH * (1 - unfold));
    gl.uniform1f(u('uWave'), s.wave);
    gl.uniform1f(u('uRipple'), s.ripple);
    gl.uniform1f(u('uFold'), 0.25 + 0.75 * unfold);
    gl.uniform2f(u('uShift'), shiftX, shiftY);
    gl.uniform4f(
      u('uPointer'),
      state.x / view.width,
      1 - state.y / view.height,
      state.touch * s.interactionStrength,
      0.32,
    );
    gl.uniform2f(u('uDrag'), state.dragX, state.dragY);
    gl.uniform4fv(u('uWaves'), waveData);
  };

  const render = () => {
    const s = getSettings();
    const unfold = ease(state.intro);
    const presence = 1 - Math.pow(1 - state.intro, 3);
    gl.bindVertexArray(vao);

    waveData.fill(0);
    waves.slice(-4).forEach((item, index) => {
      waveData.set(
        [
          item.x,
          item.y,
          item.age * 0.6,
          Math.exp(-item.age / (WAVE_LIFE * 0.45)),
        ],
        index * 4,
      );
    });

    if (s.glow > 0) {
      sizeTarget(
        Math.max(1, Math.round(canvas.width / 4)),
        Math.max(1, Math.round(canvas.height / 4)),
      );
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
      gl.viewport(0, 0, target.width, target.height);
      gl.useProgram(fieldProgram.program);
      setShared(fieldProgram, target.width, target.height, s, unfold);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.generateMipmap(gl.TEXTURE_2D);
    }

    const c = compositeProgram.uniform;
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.useProgram(compositeProgram.program);
    setShared(compositeProgram, canvas.width, canvas.height, s, unfold);
    gl.uniform3fv(c('uColor'), toRgb(s.color));
    gl.uniform3fv(c('uSheenColor'), toRgb(s.sheenColor));
    gl.uniform1f(c('uNoiseIntensity'), s.noiseIntensity);
    gl.uniform1f(c('uDepth'), s.depth);
    gl.uniform1f(c('uSheen'), s.sheen);
    gl.uniform1f(c('uGlow'), s.glow);
    gl.uniform1f(c('uLightMode'), s.lightMode ? 1 : 0);
    gl.uniform3f(
      c('uLight'),
      state.lightX,
      state.lightY,
      state.touch * s.interactionStrength,
    );
    gl.uniform2f(
      c('uStep'),
      view.ratio / canvas.width,
      view.ratio / canvas.height,
    );
    gl.uniform1f(c('uPresence'), presence);
    gl.uniform1f(c('uFade'), s.fade);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.uniform1i(c('uBloom'), 0);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  };

  const frame = (now: number) => {
    if (!visible) {
      looping = false;
      return false;
    }
    looping = true;
    const s = getSettings();
    const reduce = isReduced();
    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
    last = now;
    const flowing = !s.paused && !reduce && s.speed !== 0;
    if (flowing) state.flow += dt * 0.1 * s.speed;
    if (!s.intro || reduce) state.intro = 1;
    else if (state.intro < 1)
      state.intro = Math.min(1, state.intro + dt / INTRO_SECONDS);

    const engaged = s.mouseInteraction && pointer.inside && !reduce;
    if (engaged && state.touch < 0.01) {
      state.x = pointer.x;
      state.y = pointer.y;
    }
    const follow = 1 - Math.exp(-dt * 10);
    const prevX = state.x;
    const prevY = state.y;
    state.x += (pointer.x - state.x) * follow;
    state.y += (pointer.y - state.y) * follow;
    const velX = (state.x - prevX) / Math.max(dt, 0.001) / view.height;
    const velY = (state.y - prevY) / Math.max(dt, 0.001) / view.height;
    const dragBlend = 1 - Math.exp(-dt * 4);
    state.dragX += (clamp(velX * 0.03, -0.06, 0.06) - state.dragX) * dragBlend;
    state.dragY += (clamp(-velY * 0.03, -0.06, 0.06) - state.dragY) * dragBlend;
    state.touch +=
      ((engaged ? 1 : 0) - state.touch) *
      (1 - Math.exp(-dt * (engaged ? 3.5 : 1.4)));

    let lightGoalX = DEFAULT_LIGHT_X;
    let lightGoalY = DEFAULT_LIGHT_Y;
    if (engaged) {
      const aimX = (pointer.x / view.width - 0.5) * (view.width / view.height);
      const aimY = 0.5 - pointer.y / view.height;
      const reach = Math.hypot(aimX, aimY);
      if (reach > 0.04) {
        lightGoalX = (aimX / reach) * LIGHT_TILT;
        lightGoalY = (aimY / reach) * LIGHT_TILT;
      } else {
        lightGoalX = state.lightX;
        lightGoalY = state.lightY;
      }
    }
    const lightFollow = 1 - Math.exp(-dt * 3);
    state.lightX += (lightGoalX - state.lightX) * lightFollow;
    state.lightY += (lightGoalY - state.lightY) * lightFollow;

    for (let i = waves.length - 1; i >= 0; i--) {
      const item = waves[i];
      if (!item) continue;
      item.age += dt;
      if (item.age > WAVE_LIFE * 2.5) waves.splice(i, 1);
    }

    render();

    const settling =
      state.intro < 1 ||
      waves.length > 0 ||
      Math.abs((engaged ? 1 : 0) - state.touch) > 0.002 ||
      Math.abs(state.dragX) + Math.abs(state.dragY) > 0.0002 ||
      Math.abs(pointer.x - state.x) + Math.abs(pointer.y - state.y) > 0.3 ||
      Math.abs(lightGoalX - state.lightX) +
        Math.abs(lightGoalY - state.lightY) >
        0.001;
    looping = flowing || settling;
    if (!looping) last = 0;
    return looping;
  };

  const resize = (width: number, height: number) => {
    const s = getSettings();
    view.width = Math.max(1, width);
    view.height = Math.max(1, height);
    view.ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
    canvas.width = Math.max(1, Math.round(view.width * view.ratio));
    canvas.height = Math.max(1, Math.round(view.height * view.ratio));
    if (!looping) render();
    wake();
  };

  return {
    frame,
    update(idle) {
      const s = getSettings();
      if (s.dpr !== lastDpr) {
        lastDpr = s.dpr;
        resize(view.width, view.height);
        return;
      }
      if (idle) render();
      wake();
    },
    resize,
    setVisible(next) {
      visible = next;
      if (visible) {
        last = 0;
        wake();
      }
    },
    pointerMove(x, y, inside) {
      pointer.x = x;
      pointer.y = y;
      pointer.inside = inside;
      wake();
    },
    pointerDown(x, y, inside) {
      if (!getSettings().clickRipple || isReduced() || !inside) return;
      waves.push({ x: x / view.width, y: 1 - y / view.height, age: 0 });
      if (waves.length > 4) waves.shift();
      wake();
    },
    pointerLeave() {
      pointer.inside = false;
      wake();
    },
    resetClock() {
      last = 0;
    },
    dispose() {
      gl.deleteTexture(texture);
      gl.deleteFramebuffer(framebuffer);
      gl.deleteProgram(fieldProgram.program);
      gl.deleteProgram(compositeProgram.program);
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}

import type { SilkLook, SilkPreset } from './types';

const LOOK: SilkLook = {
  color: '#5227FF',
  sheenColor: '#ffffff',
  speed: 5,
  scale: 1,
  rotation: 0,
  sheen: 0.5,
  depth: 0.5,
  glow: 0.3,
  ripple: 1,
  wave: 1,
  variation: 0,
  noiseIntensity: 1.5,
};

const PRESETS: Record<SilkPreset, SilkLook> = {
  satin: LOOK,
  classic: { ...LOOK, sheen: 0, depth: 0, glow: 0 },
  champagne: {
    ...LOOK,
    color: '#b08d57',
    sheenColor: '#fff3dc',
    sheen: 0.6,
    depth: 0.55,
    glow: 0.35,
  },
  midnight: {
    ...LOOK,
    color: '#2a4bd7',
    speed: 3.5,
    sheen: 0.55,
    glow: 0.4,
    variation: 3,
  },
  emerald: {
    ...LOOK,
    color: '#12805f',
    sheenColor: '#e3fff4',
    rotation: 0.35,
    variation: 7,
  },
  graphite: {
    ...LOOK,
    color: '#8d8a96',
    sheen: 0.7,
    depth: 0.7,
    glow: 0.2,
    noiseIntensity: 1,
  },
  velvet: {
    ...LOOK,
    color: '#8f2747',
    sheenColor: '#ffd9e2',
    scale: 1.25,
    ripple: 1.8,
    wave: 1.6,
    speed: 4,
    depth: 0.65,
  },
};

/** The look of one of the demo presets. */
export function silkPreset(name: SilkPreset): SilkLook {
  return { ...PRESETS[name] };
}

export function isSilkPreset(value: unknown): value is SilkPreset {
  return typeof value === 'string' && value in PRESETS;
}

export const SILK_VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

const SILK = `
uniform vec2 uView;
uniform float uScale;
uniform float uRotation;
uniform float uTime;
uniform float uWave;
uniform float uRipple;
uniform float uFold;
uniform vec2 uShift;
uniform vec4 uPointer;
uniform vec2 uDrag;
uniform vec4 uWaves[4];

const float e = 2.71828182845904523536;

float noise(vec2 texCoord) {
  float G = e;
  vec2 r = (G * sin(G * texCoord));
  return fract(r.x * r.y * (1.0 + texCoord.x));
}

vec2 rotateUvs(vec2 uv, float angle) {
  float c = cos(angle);
  float s = sin(angle);
  mat2 rot = mat2(c, -s, s, c);
  return rot * uv;
}

vec2 bend(vec2 uv) {
  vec2 aspect = vec2(uView.x / uView.y, 1.0);
  vec2 offset = (uv - uPointer.xy) * aspect;
  float touch = uPointer.z * exp(-dot(offset, offset) / (uPointer.w * uPointer.w));
  uv -= uDrag * touch;
  for (int i = 0; i < 4; i++) {
    vec4 wave = uWaves[i];
    if (wave.w <= 0.0) continue;
    vec2 q = (uv - wave.xy) * aspect;
    float dist = length(q);
    float front = dist - wave.z;
    float ring = exp(-front * front * 60.0) * wave.w;
    uv += q / max(dist, 0.0001) / aspect * ring * 0.034 * sin(front * 34.0);
  }
  return uv;
}

float silk(vec2 vUv) {
  vec2 uv = rotateUvs(vUv * uScale, uRotation);
  vec2 tex = uv * uScale + uShift;
  float tOffset = uTime;
  tex.y += 0.03 * uWave * sin(8.0 * tex.x - tOffset);
  return 0.6 + 0.4 * uFold * sin(5.0 * (tex.x + tex.y + cos(3.0 * tex.x + 5.0 * tex.y) + 0.02 * tOffset) + uRipple * sin(20.0 * (tex.x + tex.y - 0.1 * tOffset)));
}
`;

/** Low-resolution pass that feeds the glow. */
export const SILK_FIELD = `#version 300 es
precision highp float;
${SILK}
out vec4 outColor;

void main() {
  vec2 vUv = gl_FragCoord.xy / uView;
  float pattern = silk(bend(vUv));
  float n = clamp((pattern - 0.2) / 0.8, 0.0, 1.0);
  outColor = vec4(pow(n, 6.0), 0.0, 0.0, 1.0);
}`;

/** Shades the fabric, adds the sheen and glow, and fades the edges. */
export const SILK_COMPOSITE = `#version 300 es
precision highp float;
${SILK}
uniform sampler2D uBloom;
uniform vec3 uColor;
uniform vec3 uSheenColor;
uniform float uNoiseIntensity;
uniform float uDepth;
uniform float uSheen;
uniform float uGlow;
uniform float uLightMode;
uniform vec3 uLight;
uniform vec2 uStep;
uniform float uPresence;
uniform float uFade;
out vec4 outColor;

float smootherstep01(float t) {
  t = clamp(t, 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

vec3 softClip(vec3 c) {
  vec3 over = max(c - 0.75, 0.0);
  return min(c, 0.75) + 0.25 * (1.0 - exp(-over * 4.0));
}

void main() {
  vec2 vUv = gl_FragCoord.xy / uView;
  vec2 coord = bend(vUv);
  float pattern = silk(coord);
  float rnd = noise(gl_FragCoord.xy);
  float n = clamp((pattern - 0.2) / 0.8, 0.0, 1.0);

  float gx = silk(coord + vec2(uStep.x, 0.0)) - pattern;
  float gy = silk(coord + vec2(0.0, uStep.y)) - pattern;
  vec3 normal = normalize(vec3(-gx * 26.0, -gy * 26.0, 1.0));
  vec3 toLight = normalize(vec3(uLight.xy, 0.85));
  float relief = 1.0 + (dot(normal, toLight) - toLight.z) * 1.8 * uDepth;
  vec3 halfway = normalize(toLight + vec3(0.0, 0.0, 1.0));
  float gloss = pow(max(dot(normal, halfway), 0.0), 48.0) * smoothstep(0.25, 0.85, n);
  float crest = pow(n, 5.0);
  float shine = (gloss * 0.85 + crest * 0.4) * uSheen * (1.0 + uLight.z * 0.6);

  float bloom = 0.0;
  if (uGlow > 0.0) {
    bloom += textureLod(uBloom, vUv, 1.0).r * 0.35;
    bloom += textureLod(uBloom, vUv, 2.0).r * 0.3;
    bloom += textureLod(uBloom, vUv, 3.0).r * 0.2;
    bloom += textureLod(uBloom, vUv, 4.0).r * 0.15;
  }

  vec3 result;
  if (uLightMode > 0.5) {
    float fold = smoothstep(0.28, 0.9, pattern);
    float specular = smoothstep(0.72, 0.98, pattern);
    vec3 shadowColor = uColor * (0.72 - 0.12 * uDepth);
    vec3 bodyColor = min(uColor * 1.18, vec3(1.0));
    vec3 lightBase = mix(shadowColor, bodyColor, fold) * mix(1.0, relief, 0.6);
    lightBase = mix(lightBase, vec3(1.0), clamp(specular * 0.92 + shine * 0.22 + bloom * uGlow * 0.2, 0.0, 1.0));
    float fineNoise = noise(gl_FragCoord.xy * 0.63 + vec2(17.0, 41.0));
    float grainSignal = (rnd + fineNoise - 1.0);
    float grainStrength = clamp(uNoiseIntensity * 0.038, 0.0, 0.16);
    result = clamp(lightBase + grainSignal * grainStrength, 0.0, 1.0);
  } else {
    float grain = rnd / 15.0 * uNoiseIntensity;
    float floorValue = mix(0.2, 0.03, uDepth);
    float curve = uDepth > 0.0 ? pow(n, 1.0 + 1.4 * uDepth) : n;
    float shade = uDepth > 0.0 ? floorValue + (1.0 - floorValue) * curve : pattern;
    vec3 tone = mix(uColor, pow(uColor, vec3(1.45)), (1.0 - n) * uDepth);
    vec3 lit = tone * shade * relief - vec3(grain);
    vec3 tint = mix(uColor, uSheenColor, 0.8);
    vec3 extra = tint * (shine + bloom * uGlow * 0.55);
    float blend = clamp((uSheen + uGlow) * 4.0, 0.0, 1.0);
    result = mix(clamp(lit, 0.0, 1.0), clamp(softClip(lit + extra), 0.0, 1.0), blend);
  }

  float edge = uFade * 0.5;
  float mask = 1.0;
  if (edge > 0.0) {
    mask = smootherstep01(vUv.x / edge) * smootherstep01((1.0 - vUv.x) / edge);
    mask *= smootherstep01(vUv.y / edge) * smootherstep01((1.0 - vUv.y) / edge);
  }
  float alpha = uPresence * mask;
  outColor = vec4(result * alpha, alpha);
}`;

export type SilkPreset =
  | 'satin'
  | 'classic'
  | 'champagne'
  | 'midnight'
  | 'emerald'
  | 'graphite'
  | 'velvet';

export interface SilkProps {
  /** How fast the folds flow. */
  speed?: number;
  /** Size of the folds. Higher values pack more in. */
  scale?: number;
  /** Color of the silk. */
  color?: string;
  /** Tint of the glossy highlights, blended with the silk color. */
  sheenColor?: string;
  /** Strength of the fine grain over the fabric. */
  noiseIntensity?: number;
  /** Turns the folds, in radians. */
  rotation?: number;
  /** Strength of the glossy highlights that run along the folds. */
  sheen?: number;
  /** How deep the folds look, from flat at 0 to deep, shaded creases at 1. */
  depth?: number;
  /** Soft glow around the brightest folds. */
  glow?: number;
  /** Strength of the fine ripples running through the folds. 0 smooths them out. */
  ripple?: number;
  /** How much the folds sway as they flow. */
  wave?: number;
  /** Picks a different arrangement of folds. Any number works. */
  variation?: number;
  /** The light turns to follow the cursor and the fabric drags along with it. */
  mouseInteraction?: boolean;
  /** How strongly the cursor moves the fabric and its light. */
  interactionStrength?: number;
  /** Clicking sends a ripple rolling through the fabric. */
  clickRipple?: boolean;
  /** The folds rise out of the dark and settle when the silk first appears. */
  intro?: boolean;
  /** Fades the edges into the page, from 0 to 1. */
  fade?: number;
  /** Draws pale silk with white highlights for light backgrounds. */
  lightMode?: boolean;
  /** Freezes the animation. */
  paused?: boolean;
  /** Maximum device pixel ratio, capped at 2. */
  dpr?: number;
  class?: string;
}

/** The tunable look shared by the demo presets. */
export interface SilkLook {
  color: string;
  sheenColor: string;
  speed: number;
  scale: number;
  rotation: number;
  sheen: number;
  depth: number;
  glow: number;
  ripple: number;
  wave: number;
  variation: number;
  noiseIntensity: number;
}

export interface SilkDemoParams extends SilkLook {
  preset: SilkPreset;
  mouseInteraction: boolean;
  interactionStrength: number;
  clickRipple: boolean;
  intro: boolean;
  fade: number;
  lightMode: boolean;
}

export interface SilkSettings extends SilkLook {
  mouseInteraction: boolean;
  interactionStrength: number;
  clickRipple: boolean;
  intro: boolean;
  fade: number;
  lightMode: boolean;
  paused: boolean;
  dpr?: number;
}

export interface SilkEngine {
  /** Advances one frame. Returns false when the loop should stop. */
  frame: (now: number) => boolean;
  /** Applies new settings: resizes on a pixel-ratio change, otherwise redraws when the loop is idle. */
  update: (idle: boolean) => void;
  resize: (width: number, height: number) => void;
  setVisible: (visible: boolean) => void;
  /** Pointer position relative to the container, in CSS px from the top-left. */
  pointerMove: (x: number, y: number, inside: boolean) => void;
  pointerDown: (x: number, y: number, inside: boolean) => void;
  pointerLeave: () => void;
  resetClock: () => void;
  dispose: () => void;
}
